preConditions.sqlCheck:
SELECT COUNT(*) FROM concept
INNER JOIN concept_name ON concept.concept_id = concept_name.concept_id
WHERE concept_name.name = 'Amendment Reason' and concept.uuid = '5c3d2d00-0ad6-434a-b27b-d820796781a4';

